    id: i + 1, name: a[0], initials: a[1], group: a[2], bw: a[3], testCount: a[4], latestDate: a[5],
    cmj: { jumpHeight: a[6], rsi: a[7], conImpulse: a[8], eccBrakingRFD: a[9], depth: a[18], adjBrk: a[19] },
