const VELO_NORMS = {"all":{"p10":73.1,"p25":75.9,"p50":83.2,"p75":85.9,"p90":89.8},"hs":{"p10":69.6,"p25":74.0,"p50":76.9,"p75":84.6,"p90":89.8},"col":{"p10":78.3,"p25":82.6,"p50":85.2,"p75":85.5,"p90":87.4}};
const VELO_ATHLETES = _VELO.map(v => ({
  name: v[0], initials: v[1], group: v[2], sessions: v[3], peakEver: v[4], avgPeak: v[5], avgAvg: v[6],
  latestPeak: v[7], latestAvg: v[8], latestDate: v[9],
  peakHistory: v[10], avgHistory: v[11], dateHistory: v[12], typeHistory: v[13], notesHistory: v[14],
  trend: v[15],
}));
const VELO_BY_NAME = Object.fromEntries(VELO_ATHLETES.map(v => [v.name, v]));
// Velo "trending" threshold: a peak-velo move smaller than this (mph) is
// session-to-session noise, not a trend (e.g. 74.7 → 74.9).
const VELO_TREND_MIN = 1.0;
// Groups that actually have velo pitchers, for the velo trending group filter.
const VELO_GROUP_SET = new Set(["all", ...VELO_ATHLETES.map(v => v.group)]);
// TrackMan/velo names differ from ForceDecks names for a few pitchers, so their
// report card never found its bullpen data. Bridge the ForceDecks spelling → velo
// row (both directions) so TrackMan attaches regardless of which spelling the
// profile uses. Format: ForceDecks/roster name → velo name.
const NAME_ALIASES = { "Patrick Rodriguez": "Pat Rodriguez", "Robert Romero": "Rob Romero", "Zach Uysal": "Zachary Uysal" };
for (const [rosterName, veloName] of Object.entries(NAME_ALIASES)) {
  if (VELO_BY_NAME[veloName] && !VELO_BY_NAME[rosterName]) VELO_BY_NAME[rosterName] = VELO_BY_NAME[veloName];
}

