const rcTier = (p) => p >= 90 ? "Elite" : p >= 75 ? "Above Average" : p >= 50 ? "Average" : p >= 25 ? "Developing" : "Building";
const rcOrd = (p) => ["th", "st", "nd", "rd"][(p % 100 - 20) % 10] || ["th", "st", "nd", "rd"][p % 100] || "th";

function RcMetric({ name, val, unit, desc, pct }) {
  const p = Math.max(0, Math.min(99, Math.round(pct)));
  const gradW = (100 / Math.max(p, 1)) * 100;
  return (
    <div className="rc-mrow">
      <div className="rc-mname">{name}</div>
      <div className="rc-mval">{val}{unit ? <span className="rc-u"> {unit}</span> : null}</div>
      <div className="rc-mdesc">{desc}</div>
      <div className="rc-mpct" style={{ color: rptBandColor(p) }}>{p}<span className="rc-ord">{rcOrd(p)}</span> <span className="rc-ptier">{rcTier(p)}</span></div>
      <div className="rc-mbar"><div className="rc-track">
        <span className="rc-tick" style={{ left: "25%" }} /><span className="rc-tick" style={{ left: "50%" }} /><span className="rc-tick" style={{ left: "75%" }} />
        <div className="rc-fill" style={{ width: p + "%" }}><div className="rc-grad" style={{ width: gradW + "%" }} /></div>
      </div></div>
    </div>
  );
}

// One DynaMo rotation column (External or Internal Rotation): bilateral peak +
// bar + asymmetry + torque/RFD sub-line. Degrades cleanly to single-side data.
function RcDynMove({ m }) {
  if (!m) return null;
  const L = m.peakN ? m.peakN[0] : null, R = m.peakN ? m.peakN[1] : null;
  const Llb = m.peakLbs ? m.peakLbs[0] : null, Rlb = m.peakLbs ? m.peakLbs[1] : null;
  const tot = (L || 0) + (R || 0);
  const lPct = tot > 0 ? Math.round(L / tot * 100) : (L != null ? 100 : 0);
  const tq = m.torqueNm || [], rf = m.rfd || [];
  const hasTq = tq[0] != null || tq[1] != null, hasRf = rf[0] != null || rf[1] != null;
  return (
    <div>
      <div className="rc-dyn-head"><span className="rc-dyn-name">{m.name.replace("Shoulder ", "")}</span><span className="rc-dyn-pos">{m.position}</span></div>
      <div className="rc-dyn-vals">
        <div className="rc-dyn-l">{dynFmt(L, 1)} <span className="rc-u">N</span><span className="rc-dyn-lb">{dynFmt(Llb, 1)} lb L</span></div>
        <div className="rc-dyn-r"><span className="rc-dyn-lb">R {dynFmt(Rlb, 1)} lb</span> {dynFmt(R, 1)} <span className="rc-u">N</span></div>
      </div>
      <div className="rc-dyn-track"><div className="rc-dyn-fl" style={{ width: lPct + "%" }} /><div className="rc-dyn-fr" style={{ width: (100 - lPct) + "%" }} /></div>
      <div className="rc-dyn-asym">{!m.asymNote ? "Single-side test" : m.asymNote === "Symmetric" ? "Symmetric · " + dynFmt(m.asymPct, 1) + "%" : dynFmt(m.asymPct, 1) + "% · " + m.asymNote}</div>
      {(hasTq || hasRf) && (
        <div className="rc-dyn-sub">
          {hasTq ? "Torque · " + dynFmt(tq[0], 1) + " N·m L / " + dynFmt(tq[1], 1) + " N·m R" : ""}
          {hasTq && hasRf ? "  •  " : ""}
          {hasRf ? "RFD · " + dynFmt(rf[0], 0) + " / " + dynFmt(rf[1], 0) + " N/s" : ""}
        </div>
      )}
    </div>
  );
}

function ReportView({ athlete, norms, hopAthlete, hopNorms, veloAthlete, offseason, hopTrend, dynamo }) {
  // Identity: the report can be seeded from any tab, so the CMJ athlete may be
  // absent (a TrackMan-only pitcher). Fall back through the sources that exist.
  const idSrc = athlete || veloAthlete || dynamo || hopAthlete || {};
  const id = { name: idSrc.name, group: idSrc.group, bw: athlete ? athlete.bw : undefined };
  const gi = GROUPS[id.group] || {};
  const hasCmjNorms = athlete ? !!norms[athlete.group] : false;
  const hasHopNorms = !!(hopNorms && hopAthlete && hopNorms[hopAthlete.group]);
  const cohortName = (hasCmjNorms || hasHopNorms) ? ("RPM " + gi.label + " athletes") : "all RPM athletes";
  const n = athlete ? (norms[athlete.group] || norms.all) : null;
  const hn = hopNorms ? (hopNorms[(hopAthlete || {}).group] || hopNorms.all) : null;
  const tmr = veloAthlete ? (_TMR[veloAthlete.name] || []) : [];
  const bp = tmr[0] || null;
  const isFemale = id.group === "fem" || FEM_SET.has(id.name);
  const bw = athlete && !isFemale ? BW_DATA[athlete.name] : null;

  // DynaMo (VALD shoulder strength) — the ER/IR rotator screen, on page 1.
  const dynTest = dynamo && dynamo.tests ? dynPrimaryTest(dynamo.tests) : undefined;
  const dynCore = dynTest ? dynTest.movements.filter(m => DYN_CORE.includes(m.name)) : [];
  const dynER = dynCore.find(m => m.name === "External Rotation");
  const dynIR = dynCore.find(m => m.name === "Internal Rotation");
  const hasDyn = !!(dynTest && (dynER || dynIR));
  const dynArm = dynamo && dynamo.arm === "L" ? "Left" : dynamo && dynamo.arm === "R" ? "Right" : null;
  const dynDate = dynTest && dynTest.date ? new Date(dynTest.date + "T00:00:00").toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : "";
  const dob = dynamo && dynamo.dob ? new Date(dynamo.dob.slice(0, 10) + "T00:00:00").toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : null;

  const prChg = (first, best) => (first && best ? Math.round(((best - first) / Math.abs(first)) * 1000) / 10 : 0);

  // CMJ metric cards
  const cmjRows = athlete ? [
    { name: "Jump Height", val: athlete.cmj.jumpHeight + "″", desc: "How high the athlete jumps. The headline measure of lower-body power.", pct: cP(athlete.cmj.jumpHeight, n.cmjHeight) },
    { name: "RSI-modified", val: athlete.cmj.rsi, desc: "Jump height relative to time on the ground. Explosiveness per second of effort.", pct: cP(athlete.cmj.rsi, n.rsiMod) },
    { name: "Concentric Impulse", val: athlete.cmj.conImpulse, unit: "N·s", desc: "Total drive applied through the push-off. Closely tied to takeoff velocity.", pct: cP(athlete.cmj.conImpulse, n.conImpulse) },
    { name: "Eccentric Braking Force", val: athlete.cmj.eccBrakingRFD.toFixed(2), unit: "×BW", desc: "How forcefully the body absorbs and reverses the dip in a jump, relative to bodyweight. Reflects eccentric loading; built by strength training." + (athlete.cmj.depth ? " This jump: ~" + Math.round(athlete.cmj.depth) + " cm countermovement dip." : ""), pct: cP(athlete.cmj.eccBrakingRFD, n.eccBrakingRFD) },
  ] : [];
  const hopRows = (hopAthlete && hn) ? [
    { name: "Reactive Strength Index", val: hopAthlete.hop.rsi, desc: "Flight time divided by contact time. How efficiently ground contact turns into explosive hops.", pct: cP(hopAthlete.hop.rsi, hn.rsi) },
    { name: "Contact Time", val: hopAthlete.hop.ct, unit: "ms", desc: "Time on the ground between hops. Shorter contact with maintained height shows better stiffness.", pct: cP(hopAthlete.hop.ct, hn.ct, true) },
    { name: "Flight Time", val: hopAthlete.hop.ft, unit: "ms", desc: "Time in the air between hops. Longer flight means more force in less ground time.", pct: cP(hopAthlete.hop.ft, hn.ft) },
    ...(hopAthlete.hop.pfbm ? [{ name: "Relative Peak Force", val: hopAthlete.hop.pfbm, unit: "N/BW", desc: "Peak ground force divided by bodyweight. Force output in a very short window.", pct: cP(hopAthlete.hop.pfbm, hn.pfbm) }] : []),
  ] : [];

  // Progress (first session -> personal best)
  const progRows = [];
  if (athlete && offseason && offseason.sessions >= 2) {
    progRows.push({ lab: "Jump Height", first: offseason.jhFirst, best: athlete.best.jumpHeight, unit: "″", chg: prChg(offseason.jhFirst, athlete.best.jumpHeight) });
    progRows.push({ lab: "RSI-modified", first: offseason.rsiFirst, best: athlete.best.rsi, unit: "", chg: prChg(offseason.rsiFirst, athlete.best.rsi) });
    progRows.push({ lab: "Concentric Impulse", first: offseason.ppFirst, best: athlete.best.conImpulse, unit: "", chg: prChg(offseason.ppFirst, athlete.best.conImpulse) });
  }
  if (hopAthlete && hopTrend && hopTrend.sessions >= 2) {
    progRows.push({ lab: "Hop RSI", first: hopTrend.rsi_first, best: hopAthlete.best.rsi, unit: "", chg: prChg(hopTrend.rsi_first, hopAthlete.best.rsi) });
    progRows.push({ lab: "Contact Time", first: hopTrend.ct_first, best: hopAthlete.best.ct, unit: " ms", chg: prChg(hopTrend.ct_first, hopAthlete.best.ct), invert: true });
  }
  const hasProg = progRows.length > 0;
  const hasBw = !!(bw && bw.history && bw.history.length >= 2);
  const hasProgRow = hasProg || hasBw;

  const hasStrength = athlete || (hopAthlete && hn) || hasDyn;
  const pages = (hasStrength ? 1 : 0) + (veloAthlete ? 1 : 0);
  const pageStyle = { fontFamily: "'DM Sans', system-ui, -apple-system, sans-serif", maxWidth: 720, margin: "0 auto 28px", padding: "22px 26px", color: "#1B2A44", background: "#fff", boxShadow: "0 1px 6px rgba(0,0,0,0.12)" };

  const Foot = ({ dyn }) => (
    <div className="rc-foot">RPM Strength {"·"} Queens, NY &nbsp;|&nbsp; Data: VALD ForceDecks{dyn ? " + DynaMo" : ""} &nbsp;|&nbsp; Generated {LAST_UPDATED} &nbsp;|&nbsp; Percentiles vs {cohortName}.</div>
  );

  return (
    <div id="report-content" style={{ background: "#EDEEF1", padding: "18px 0" }}>
      <style>{RC_CSS}</style>

      {/* ── SHEET 1: Strength evaluation (CMJ + Hop + Progress + DynaMo) ── */}
      {hasStrength && (
        <div className="rpt-page" style={pageStyle}>
          <div className="rc-top">
            <div>
              <div className="rc-eyebrow">Athlete Evaluation Report</div>
              <div className="rc-aname">{id.name}</div>
              <div className="rc-ameta">{gi.label}{FEM_SET.has(id.name) ? " · Female Athletes" : ""}{dob ? " · DOB " + dob : ""}{(id.bw && !isFemale) ? " · " + id.bw + " lb" : ""}</div>
            </div>
            <img src={RPM_LOGO_DARK} alt="RPM Strength" />
          </div>
          <div className="rc-cohort">Percentiles rank against <b>{cohortName}</b>. Colors: <b style={{ color: "#C0392B" }}>building</b> {"→"} <b style={{ color: "#B7791F" }}>average</b> {"→"} <b style={{ color: "#1B7F4B" }}>strong</b>. Bar = 0 to 99th percentile.</div>

          {(cmjRows.length > 0 || hopRows.length > 0) && (
            <div className={"rc-grid2" + ((cmjRows.length > 0) !== (hopRows.length > 0) ? " rc-solo" : "")}>
              {cmjRows.length > 0 && (
                <div className="rc-card">
                  <div className="rc-ctitle">Countermovement Jump</div>
                  <div className="rc-csub">Lower-body explosive power {"·"} VALD ForceDecks</div>
                  {cmjRows.map((r, i) => <RcMetric key={i} {...r} />)}
                </div>
              )}
              {hopRows.length > 0 && (
                <div className="rc-card">
                  <div className="rc-ctitle">Hop Test {"—"} Reactive Strength</div>
                  <div className="rc-csub">Reactive strength over repeated hops {"·"} VALD ForceDecks</div>
                  {hopRows.map((r, i) => <RcMetric key={i} {...r} />)}
                </div>
              )}
            </div>
          )}

          {/* Progress PR + bodyweight sparkline (sits above DynaMo) */}
          {hasProgRow && (
            <div className={"rc-grid2" + (hasProg !== hasBw ? " rc-solo" : "")} style={{ marginTop: 13 }}>
              {hasProg && (
                <div className="rc-card">
                  <div className="rc-ctitle">Progress {"·"} PR Tracker</div>
                  <div className="rc-csub">First tested session {"→"} personal best</div>
                  {progRows.map((r, i) => {
                    const up = r.invert ? r.chg < 0 : r.chg > 0;
                    const col = r.chg === 0 ? "#5B6470" : up ? "#1B7F4B" : "#C0392B";
                    return (
                      <div key={i} className="rc-prog">
                        <div className="rc-prog-lab">{r.lab}</div>
                        <div className="rc-prog-val">{r.first}{r.unit} {"→"} <b style={{ color: "#1B2A44" }}>{r.best}{r.unit}</b></div>
                        <div className="rc-prog-chg" style={{ color: col }}>{r.chg > 0 ? "+" : ""}{Number(r.chg).toFixed(1)}%</div>
                      </div>
                    );
                  })}
                </div>
              )}
              {hasBw && (() => {
                const h = bw.history, dts = bw.dates || [];
                const mn = Math.min(...h) * 0.995, mx = Math.max(...h) * 1.005, rg = (mx - mn) || 1;
                const W = 600, H = 46;
                const pts = h.map((v, j) => ({ x: (j / Math.max(1, h.length - 1)) * W, y: H - ((v - mn) / rg) * H }));
                const dPath = pts.map((pt, j) => (j === 0 ? "M" : "L") + pt.x.toFixed(1) + "," + pt.y.toFixed(1)).join(" ");
                const aPath = dPath + " L" + W + "," + H + " L0," + H + " Z";
                const ch = bw.change;
                return (
                  <div className="rc-card">
                    <div className="rc-ctitle">Bodyweight</div>
                    <div className="rc-csub">Tracked across every testing session</div>
                    <div className="rc-bw-top">
                      <div className="rc-bw-big">{h[0]} {"→"} {bw.current} lbs</div>
                      <div className="rc-bw-chg" style={{ color: ch > 0 ? "#16A34A" : ch < 0 ? "#DC2626" : "#5B6470" }}>{ch > 0 ? "+" : ""}{ch} lbs</div>
                    </div>
                    <svg viewBox={"0 0 " + W + " " + H} style={{ display: "block", width: "100%", marginTop: 6 }}>
                      <path d={aPath} fill="rgba(27,42,68,0.07)" />
                      <path d={dPath} fill="none" stroke="#1B2A44" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                      <circle cx={pts[pts.length - 1].x} cy={pts[pts.length - 1].y} r="4" fill="#DD5228" />
                    </svg>
                    <div className="rc-bw-dates"><span>{dts[0]}</span><span>{dts[dts.length - 1]}</span></div>
                  </div>
                );
              })()}
            </div>
          )}

          {/* DynaMo shoulder strength (pushed below progress) */}
          {hasDyn && (
            <div className="rc-card rc-full">
              <div className="rc-ctitle">DynaMo Shoulder Strength</div>
              <div className="rc-csub">Isometric rotator-cuff testing{dynArm ? " · throwing arm: " + dynArm : ""} {"·"} VALD DynaMo{dynDate ? " · " + dynDate : ""}</div>
              <div className="rc-dyn-grid">
                <RcDynMove m={dynER} />
                <RcDynMove m={dynIR} />
              </div>
              {dynTest.erIr && (dynTest.erIr.left != null || dynTest.erIr.right != null) && (
                <div className="rc-ratio-wrap">
                  <div className={"rc-ratio-box" + (dynArm === "Left" ? " rc-throw" : "")}>
                    {dynArm === "Left" ? <div className="rc-ratio-tag">Throwing arm</div> : null}
                    <div className="rc-ratio-num" style={{ color: dynArm === "Left" ? "#DD5228" : "#1B2A44" }}>{dynTest.erIr.left == null ? "–" : Number(dynTest.erIr.left).toFixed(2)}</div>
                    <div className="rc-ratio-lab">Left arm</div>
                  </div>
                  <div className={"rc-ratio-box" + (dynArm === "Right" ? " rc-throw" : "")}>
                    {dynArm === "Right" ? <div className="rc-ratio-tag">Throwing arm</div> : null}
                    <div className="rc-ratio-num" style={{ color: dynArm === "Right" ? "#DD5228" : "#1B2A44" }}>{dynTest.erIr.right == null ? "–" : Number(dynTest.erIr.right).toFixed(2)}</div>
                    <div className="rc-ratio-lab">Right arm</div>
                  </div>
                  <div className="rc-ratio-side">
                    <b>External : Internal Rotation Ratio</b>
                    <div className="rc-ratio-note">Balance between the muscles that decelerate the arm (ER) and those that accelerate it (IR). A ratio near or above 1.00 indicates external rotators keeping pace {"—"} shown for clinical reference, reviewed by the athlete{"’"}s care team, not a diagnosis.</div>
                  </div>
                </div>
              )}
            </div>
          )}
          <Foot dyn={hasDyn} />
        </div>
      )}

      {/* ── SHEET 2: TrackMan pitching ── */}
      {veloAthlete && (
        <div className="rpt-page" style={pageStyle}>
          <div className="rc-top">
            <div>
              <div className="rc-eyebrow">Pitching Report {"·"} TrackMan</div>
              <div className="rc-aname">{id.name}</div>
              <div className="rc-ameta">{gi.label} {"·"} {veloAthlete.sessions} velo sessions {"·"} last {veloAthlete.latestDate}</div>
            </div>
            <img src={RPM_LOGO_DARK} alt="RPM Strength" />
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8, marginTop: 12 }}>
            {[["PEAK FB EVER", veloAthlete.peakEver + " mph"], ["AVG PEAK", veloAthlete.avgPeak + " mph"],
              ["LATEST PEAK", veloAthlete.latestPeak + " mph"],
              ["PERCENTILE", (() => { const p = veloPct(veloAthlete.peakEver); return p + rcOrd(p); })()]].map(([l, v], i) => (
              <div key={i} style={{ border: "1px solid " + RPT.line, borderRadius: 8, padding: "8px 6px", textAlign: "center" }}>
                <div style={{ fontSize: 14, fontWeight: 800, color: i === 3 ? rptBandColor(veloPct(veloAthlete.peakEver)) : RPT.navy }}>{v}</div>
                <div style={{ fontSize: 7.5, color: RPT.lgray, letterSpacing: 0.4, marginTop: 2 }}>{l}</div>
              </div>
            ))}
          </div>
          <div style={{ marginTop: 8 }}><RptPctBar pct={veloPct(veloAthlete.peakEver)} /></div>
          <div style={{ fontSize: 8.5, color: RPT.lgray, marginTop: 2 }}>Peak fastball percentile among {VELO_ATHLETES.length} active RPM pitchers.</div>
          {bp && (<>
            <RptSection title={"Latest Bullpen · " + bp.df + " · " + bp.st + " · " + bp.tot + " pitches" + (bp.note ? " · " + bp.note : "")}>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr>{["Pitch", "#", "Use", "Avg", "Max", "IVB", "HB", "Spin", "Eff"].map((h, i) => (
                  <th key={i} style={{ padding: "4px 6px", textAlign: i > 0 ? "right" : "left", fontSize: 8, textTransform: "uppercase", color: RPT.gray, background: RPT.thbg, borderBottom: "1px solid " + RPT.line }}>{h}</th>
                ))}</tr></thead>
                <tbody>{bp.types.map((t, i) => (
                  <tr key={i}>
                    <td style={{ padding: "4px 6px", fontSize: 10.5, fontWeight: 700, color: RPT.navy, borderBottom: "1px solid " + RPT.line }}>
                      <span style={{ display: "inline-block", width: 7, height: 7, borderRadius: "50%", background: pColor(t[0]), marginRight: 5, verticalAlign: "middle" }} />{t[0]}
                    </td>
                    {[t[1], Math.round((t[1] / bp.tot) * 100) + "%", t[2] != null ? t[2].toFixed(1) : "–", t[3] != null ? t[3].toFixed(1) : "–",
                      t[4] != null ? t[4].toFixed(1) : "–", t[5] != null ? t[5].toFixed(1) : "–", t[6] != null ? t[6] : "–",
                      t[10] != null ? t[10] + "%" : "–"].map((v, j) => (
                      <td key={j} style={{ padding: "4px 6px", textAlign: "right", fontSize: 10.5, color: "#1a1a1a", borderBottom: "1px solid " + RPT.line }}>{v}</td>
                    ))}
                  </tr>
                ))}</tbody>
              </table>
            </RptSection>
            <div style={{ display: "flex", gap: 14, marginTop: 10 }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 10, fontWeight: 800, color: RPT.navy, marginBottom: 4 }}>Pitch Movement <span style={{ fontWeight: 400, color: RPT.lgray }}>(pitcher{"’"}s view)</span></div>
                <MovementPlot session={bp} light />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 10, fontWeight: 800, color: RPT.navy, marginBottom: 4 }}>Release Point</div>
                <ReleasePlot session={bp} light />
                <div style={{ display: "flex", flexWrap: "wrap", gap: 7, marginTop: 6 }}>
                  {bp.types.map((t, i) => (
                    <span key={i} style={{ fontSize: 8, fontWeight: 700, color: RPT.gray }}>
                      <span style={{ display: "inline-block", width: 6, height: 6, borderRadius: "50%", background: pColor(t[0]), marginRight: 3 }} />{PITCH_ABBR[t[0]] || t[0]}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </>)}
          <RptSection title="Recent Velo Sessions">
            <div>
              {veloAthlete.dateHistory.map((d, i) => ({ d, t: veloAthlete.typeHistory[i], p: veloAthlete.peakHistory[i], a: veloAthlete.avgHistory[i] })).reverse().slice(0, 5).map((s, i) => (
                <div key={i} style={{ display: "flex", padding: "4px 0", borderBottom: "1px solid " + RPT.line, fontSize: 10.5 }}>
                  <div style={{ width: 90, color: RPT.gray }}>{s.d}</div>
                  <div style={{ flex: 1, color: RPT.gray }}>{s.t}</div>
                  <div style={{ width: 70, textAlign: "right", fontWeight: 800, color: RPT.navy }}>{s.p} mph</div>
                  <div style={{ width: 70, textAlign: "right", color: RPT.gray }}>avg {s.a}</div>
                </div>
              ))}
            </div>
          </RptSection>
          <div className="rc-foot">RPM Strength {"·"} Queens, NY &nbsp;|&nbsp; Data: TrackMan &nbsp;|&nbsp; Generated {LAST_UPDATED} &nbsp;|&nbsp; rpmstrength.coach</div>
        </div>
      )}
    </div>
  );
}

function BodyweightChart({ athleteName, group }) {
  if (group === "fem" || FEM_SET.has(athleteName)) return null;
  const data = BW_DATA[athleteName];
  if (!data || data.history.length < 3) return null;

  const changeColor = data.change > 0 ? "#4FFFB0" : data.change < 0 ? "#FF6B6B" : "#6B7280";

  return (
    <div style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)", borderRadius: 16, padding: "18px 16px", marginBottom: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontSize: 18 }}>{"💪"}</span>
          <span style={{ fontSize: 14, fontWeight: 600, color: "#E0E0E0" }}>Bodyweight</span>
        </div>
        <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
          <span style={{ fontSize: 20, fontWeight: 700, color: "#fff" }}>{data.current}<span style={{ fontSize: 11, fontWeight: 400, color: "#8A8F98" }}> lbs</span></span>
        </div>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <span style={{ fontSize: 10, color: "#6B7280" }}>Weekly avg {"·"} {data.history.length} weeks since offseason</span>
        <span style={{ fontSize: 12, fontWeight: 700, color: changeColor }}>{data.change > 0 ? "+" : ""}{data.change} lbs</span>
      </div>
      <SL data={data.history} color="#60A5FA" width={280} height={60} dates={data.dates} unit=" lbs" />
    </div>
  );
}

function AsymIT({ title, desc, children }) {
  const [o, setO] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!o) return;
    function h(e) { if (ref.current && !ref.current.contains(e.target)) setO(false); }
    document.addEventListener("mousedown", h); document.addEventListener("touchstart", h);
    return () => { document.removeEventListener("mousedown", h); document.removeEventListener("touchstart", h); };
  }, [o]);
  return (
    <span ref={ref} style={{ position: "relative", display: "inline-flex", alignItems: "center", gap: 4 }}>
      {children}
      <span onClick={(e) => { e.stopPropagation(); setO(!o); }}
        onMouseEnter={() => { if (window.matchMedia("(hover:hover)").matches) setO(true); }}
        onMouseLeave={() => { if (window.matchMedia("(hover:hover)").matches) setO(false); }}
        style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 15, height: 15, borderRadius: "50%", fontSize: 8, fontWeight: 700, background: o ? "rgba(79,255,176,0.2)" : "rgba(255,255,255,0.08)", color: o ? "#4FFFB0" : "#6B7280", cursor: "pointer", flexShrink: 0 }}>?</span>
      {o && (
        <div style={{ position: "absolute", bottom: "calc(100% + 8px)", left: "50%", transform: "translateX(-50%)", width: 270, background: "#1E2128", border: "1px solid rgba(79,255,176,0.15)", borderRadius: 12, padding: "14px 16px", zIndex: 200, boxShadow: "0 12px 40px rgba(0,0,0,0.6)" }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: "#4FFFB0", marginBottom: 6 }}>{title}</div>
          <div style={{ fontSize: 11, color: "#B0B4BC", lineHeight: 1.6 }}>{desc}</div>
        </div>
      )}
    </span>
  );
}

function AsymmetrySection({ athleteName }) {
  const data = ASYMMETRY[athleteName];
  if (!data) return null;

  const metrics = [
    { label: "Concentric Impulse", value: data.conImpulse, side: data.conSide, desc: "Measures the balance of total push-off force between legs during the jump. A significant imbalance here means one leg is doing more of the work to get off the ground." },
    { label: "Ecc Braking Impulse", value: data.eccBraking, side: data.eccSide, desc: "Measures how evenly each leg absorbs force during the downward phase of the jump. Imbalances here can indicate compensation patterns and increased injury risk to the overloaded side." },
    { label: "Conc Peak Force", value: data.concPeakForce, side: data.cpfSide, desc: "Compares the maximum force each leg produces at the most explosive moment of the jump. Large differences may point to strength deficits or guarding behavior from a prior injury." },
  ];

  function getColor(val) {
    if (val <= 10) return "#4FFFB0";
    if (val <= 15) return "#FFB020";
    return "#FF6B6B";
  }

  function getLabel(val) {
    if (val <= 10) return "Symmetrical";
    if (val <= 15) return "Monitor";
    return "Flag";
  }

  const maxAsym = Math.max(data.conImpulse, data.eccBraking, data.concPeakForce);

  return (
    <div style={{ background: "rgba(255,255,255,0.03)", border: `1px solid ${maxAsym > 15 ? "rgba(255,107,107,0.2)" : maxAsym > 10 ? "rgba(255,176,32,0.15)" : "rgba(255,255,255,0.06)"}`, borderRadius: 16, padding: "18px 16px", marginBottom: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontSize: 18 }}>{"\u2696\uFE0F"}</span>
          <span style={{ fontSize: 14, fontWeight: 600, color: "#E0E0E0" }}>Left / Right Asymmetry</span>
        </div>
        <div style={{ fontSize: 9, fontWeight: 700, color: getColor(maxAsym), background: getColor(maxAsym) + "15", padding: "3px 10px", borderRadius: 10 }}>{getLabel(maxAsym)}</div>
      </div>

      <div style={{ fontSize: 10, color: "#8A8F98", lineHeight: 1.5, marginBottom: 14, padding: "8px 10px", background: "rgba(255,255,255,0.02)", borderRadius: 8 }}>
        Asymmetry under 10% is considered normal. Between 10-15% should be monitored. Above 15% may increase injury risk and should be addressed in programming.
      </div>

      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 16, marginBottom: 16, padding: "10px 0" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 10, color: "#6B7280", marginBottom: 4 }}>LEFT</div>
          <div style={{ fontSize: 18, fontWeight: 700, color: data.domSide === "L" ? "#60A5FA" : "#6B7280" }}>{data.lImpulse}<span style={{ fontSize: 10, fontWeight: 400, color: "#6B7280" }}> N{"\u00b7"}s</span></div>
          {data.domSide === "L" && <div style={{ fontSize: 8, color: "#60A5FA", fontWeight: 700, marginTop: 2 }}>DOMINANT</div>}
        </div>
        <div style={{ width: 1, height: 36, background: "rgba(255,255,255,0.1)" }} />
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 10, color: "#6B7280", marginBottom: 4 }}>RIGHT</div>
          <div style={{ fontSize: 18, fontWeight: 700, color: data.domSide === "R" ? "#60A5FA" : "#6B7280" }}>{data.rImpulse}<span style={{ fontSize: 10, fontWeight: 400, color: "#6B7280" }}> N{"\u00b7"}s</span></div>
          {data.domSide === "R" && <div style={{ fontSize: 8, color: "#60A5FA", fontWeight: 700, marginTop: 2 }}>DOMINANT</div>}
        </div>
      </div>

      {metrics.map((m, i) => {
        const c = getColor(m.value);
        const pos = 50 + (m.side === "R" ? 1 : -1) * Math.min(m.value, 30) / 30 * 50;
        return (
          <div key={i} style={{ marginBottom: i < metrics.length - 1 ? 14 : 0 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
              <AsymIT title={m.label} desc={m.desc}><span style={{ fontSize: 11, fontWeight: 600, color: "#C0C4CC" }}>{m.label}</span></AsymIT>
              <span style={{ fontSize: 12, fontWeight: 700, color: c }}>{m.value}% <span style={{ fontSize: 9, fontWeight: 600, color: "#8A8F98" }}>{m.side}</span></span>
            </div>
            <div style={{ position: "relative", height: 10, background: "rgba(255,255,255,0.04)", borderRadius: 5 }}>
              <div style={{ position: "absolute", left: 0, top: 0, width: "50%", height: "100%", background: "rgba(96,165,250,0.06)", borderRadius: "5px 0 0 5px" }} />
              <div style={{ position: "absolute", left: "50%", top: 0, width: "50%", height: "100%", background: "rgba(255,107,107,0.06)", borderRadius: "0 5px 5px 0" }} />
              <div style={{ position: "absolute", left: "50%", top: -2, width: 2, height: 14, background: "rgba(255,255,255,0.2)", transform: "translateX(-50%)" }} />
              <div style={{ position: "absolute", left: pos + "%", top: -3, width: 16, height: 16, borderRadius: "50%", background: c, border: "2px solid #0A0C10", transform: "translateX(-50%)", boxShadow: "0 0 8px " + c + "50", transition: "left 0.6s ease" }} />
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 3 }}>
              <span style={{ fontSize: 8, color: "#60A5FA" }}>L dominant</span>
              <span style={{ fontSize: 8, color: "#6B7280" }}>balanced</span>
              <span style={{ fontSize: 8, color: "#FF6B6B" }}>R dominant</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}




function ProfileSearch({ athletes, onSelect, testLabel }) {
  const [q, setQ] = useState("");
  const sortByLast = (a, b) => a.name.split(" ").slice(-1)[0].localeCompare(b.name.split(" ").slice(-1)[0]);
  const matches = q.length > 0
    ? athletes.filter(a => a.name.toLowerCase().includes(q.toLowerCase())).sort(sortByLast)
    : [...athletes].sort(sortByLast);

  return (
    <div style={{ padding: "0 4px" }}>
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <div style={{ fontSize: 20, fontWeight: 700, color: "#E0E0E0", marginBottom: 6 }}>Find Your Athlete</div>
        <div style={{ fontSize: 12, color: "#6B7280" }}>Search by name to view their {testLabel} profile</div>
      </div>
      <div style={{ position: "relative", marginBottom: 16 }}>
        <input
          type="text"
          placeholder="Search athletes..."
          value={q}
          onChange={e => setQ(e.target.value)}
          autoFocus
          style={{
            width: "100%", padding: "14px 16px 14px 40px", border: "1px solid rgba(255,255,255,0.1)",
            borderRadius: 14, fontSize: 14, color: "#fff", background: "rgba(255,255,255,0.05)",
            outline: "none", boxSizing: "border-box",
          }}
          onFocus={e => e.target.style.borderColor = "#4FFFB040"}
          onBlur={e => e.target.style.borderColor = "rgba(255,255,255,0.1)"}
        />
        <div style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: "#6B7280" }}>{"🔍"}</div>
      </div>
      <div style={{ maxHeight: 400, overflowY: "auto" }}>
        {matches.map(a => {
          const ag = GROUPS[a.group];
          return (
            <div key={a.name} onMouseDown={(e) => { e.preventDefault(); onSelect(a); }} onTouchEnd={(e) => { e.preventDefault(); onSelect(a); }}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 14px", cursor: "pointer", borderBottom: "1px solid rgba(255,255,255,0.04)", borderRadius: 10 }}>
              <div style={{ width: 36, height: 36, borderRadius: "50%", background: "linear-gradient(135deg, " + ag.color + "40, " + ag.color + "15)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, color: ag.color }}>{a.initials}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 13, fontWeight: 600, color: "#E0E0E0" }}>{a.name}</div>
                <div style={{ fontSize: 10, color: ag.color }}>{ag.label} {"·"} {a.testCount} sessions</div>
              </div>
            </div>
          );
        })}
        {matches.length === 0 && <div style={{ padding: 20, textAlign: "center", fontSize: 12, color: "#6B7280" }}>No athletes found</div>}
      </div>
    </div>
  );
}

// True percentile rank among active RPM pitchers (peak FB velo). Replaces the
// old two-anchor interpolation between p10 and p90, which clamped everyone at
// or below the 10th-percentile velo to "1st" (~6 of 56 pitchers) and everyone
// at or above the 90th to "99th".
function veloPct(peak) {
  let below = 0, ties = 0;
  for (const v of VELO_ATHLETES) { if (v.peakEver < peak) below++; else if (v.peakEver === peak) ties++; }
  const n = VELO_ATHLETES.length || 1;
  return Math.min(99, Math.max(1, Math.round(((below + 0.5 * ties) / n) * 100)));
}

function VeloTab({ onSelect }) {
  const [sort, setSort] = useState("peak");
  const [vGroup, setVGroup] = useState("all");
  
  const groupFiltered = vGroup === "all" ? VELO_ATHLETES : VELO_ATHLETES.filter(a => a.group === vGroup);
  const sorted_athletes = [...groupFiltered].sort((a, b) => {
    if (sort === "peak") return b.peakEver - a.peakEver;
    if (sort === "avg") return b.avgPeak - a.avgPeak;
    if (sort === "trend") return b.trend - a.trend;
    if (sort === "latest") return b.latestPeak - a.latestPeak;
    return b.sessions - a.sessions;
  });

  return (
    <div style={{ padding: "0 16px" }}>
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <div style={{ fontSize: 18, fontWeight: 700, color: "#fff", marginBottom: 4 }}>{"\u26BE"} Velocity Leaderboard</div>
        <div style={{ fontSize: 11, color: "#6B7280" }}>Peak FB Velo · {VELO_ATHLETES.length} pitchers · TrackMan</div>
      </div>

      <div style={{ display: "flex", gap: 6, justifyContent: "center", marginBottom: 16, flexWrap: "wrap" }}>
        {[["peak","Peak Ever"],["latest","Latest"],["avg","Avg Peak"],["trend","Trending"]].map(([k, l]) => (
          <button key={k} onClick={() => setSort(k)} style={{
            padding: "6px 12px", borderRadius: 16, border: "none", cursor: "pointer", fontSize: 11, fontWeight: 600,
            background: sort === k ? "rgba(79,255,176,0.15)" : "rgba(255,255,255,0.04)",
            color: sort === k ? "#4FFFB0" : "#6B7280",
          }}>{l}</button>
        ))}
      </div>

      <div style={{ display: "flex", gap: 6, justifyContent: "center", marginBottom: 16, flexWrap: "wrap" }}>
        {[["all","All"],["ms","Middle School"],["hs","High School"],["col","College"],["ml","Men's League"],["pro","Pro"]].map(([k, l]) => (
          <button key={k} onClick={() => setVGroup(k)} style={{
            padding: "5px 10px", borderRadius: 14, border: "none", cursor: "pointer", fontSize: 10, fontWeight: 600,
            background: vGroup === k ? ((GROUPS[k] || {}).color || "#4FFFB0") + "22" : "rgba(255,255,255,0.03)",
            color: vGroup === k ? (GROUPS[k] || {}).color || "#4FFFB0" : "#6B7280",
          }}>{l}</button>
        ))}
      </div>

      {sorted_athletes.map((a, i) => {
        const pct = veloPct(a.peakEver);
        const tierColor = pct >= 80 ? "#4FFFB0" : pct >= 60 ? "#60A5FA" : pct >= 35 ? "#FFB020" : "#FF8C42";
        const mn = Math.min(...a.peakHistory) * 0.97;
        const mx = Math.max(...a.peakHistory) * 1.03;
        const rg = mx - mn || 1;
        const pts = a.peakHistory.map((v, j) => ({ x: (j / Math.max(1, a.peakHistory.length - 1)) * 100, y: 28 - ((v - mn) / rg) * 28 }));
        const sparkPath = pts.map((p, j) => (j === 0 ? "M" : "L") + p.x.toFixed(1) + "," + p.y.toFixed(1)).join(" ");
        
        return (
          <div key={a.name} onClick={() => onSelect && onSelect(a.name)} style={{
            background: "rgba(255,255,255,0.03)", borderRadius: 14, padding: "14px 16px", marginBottom: 8,
            border: "1px solid rgba(255,255,255,0.05)",
          }}>
            <div style={{ cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 28, height: 28, borderRadius: "50%", background: tierColor + "22", color: tierColor,
                  display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 800 }}>
                  {i + 1}
                </div>
                <div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "#fff" }}>{a.name}</div>
                  <div style={{ fontSize: 10, color: "#6B7280" }}><span style={{ color: (GROUPS[a.group] || {}).color || "#6B7280" }}>{(GROUPS[a.group] || {}).shortLabel || ""}</span> · {a.sessions} sessions · {a.latestDate}</div>
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: 20, fontWeight: 800, color: tierColor }}>{sort === "avg" ? a.avgPeak : sort === "latest" ? a.latestPeak : sort === "trend" ? (a.trend > 0 ? "+" : "") + a.trend : a.peakEver}</div>
                <div style={{ fontSize: 9, color: "#6B7280" }}>
                  {sort === "avg" ? "avg peak" : sort === "latest" ? "latest peak" : sort === "trend" ? "mph trend" : "mph peak"}
                </div>
              </div>
            </div>
            
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div style={{ display: "flex", gap: 12, fontSize: 10, color: "#8A8F98" }}>
                <span>Peak: <span style={{ color: "#fff", fontWeight: 600 }}>{a.peakEver}</span></span>
                <span>Avg: <span style={{ color: "#fff", fontWeight: 600 }}>{a.avgAvg}</span></span>
                <span style={{ color: a.trend > 0 ? "#4FFFB0" : a.trend < 0 ? "#FF6B6B" : "#8A8F98" }}>
                  {a.trend > 0 ? "\u2191" : a.trend < 0 ? "\u2193" : "\u2192"}{Math.abs(a.trend)} mph
                </span>
              </div>
              {a.peakHistory.length >= 2 && (
                <svg width={100} height={28} style={{ flexShrink: 0 }}>
                  <defs><linearGradient id={"vg"+i} x1="0" y1="0" x2="1" y2="0">
                    <stop offset="0%" stopColor={tierColor} stopOpacity="0.3"/>
                    <stop offset="100%" stopColor={tierColor}/>
                  </linearGradient></defs>
                  <path d={sparkPath} fill="none" stroke={"url(#vg"+i+")"} strokeWidth="2" strokeLinecap="round"/>
                </svg>
              )}
            </div>
          </div>
        );
      })}
      
      <div style={{ marginTop: 16, padding: 16, background: "rgba(255,255,255,0.02)", borderRadius: 14, border: "1px solid rgba(255,255,255,0.05)" }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: "#fff", marginBottom: 8 }}>{"\uD83D\uDCCA"} Facility Benchmarks</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          {[["90th", (VELO_NORMS[vGroup] || VELO_NORMS.all || {}).p90],["75th", (VELO_NORMS[vGroup] || VELO_NORMS.all || {}).p75],["50th", (VELO_NORMS[vGroup] || VELO_NORMS.all || {}).p50],["25th", (VELO_NORMS[vGroup] || VELO_NORMS.all || {}).p25]].map(([l, v]) => (
            <div key={l} style={{ display: "flex", justifyContent: "space-between", padding: "6px 10px", background: "rgba(255,255,255,0.03)", borderRadius: 8 }}>
              <span style={{ fontSize: 11, color: "#6B7280" }}>{l}</span>
              <span style={{ fontSize: 11, fontWeight: 700, color: "#fff" }}>{v} mph</span>
            </div>
          ))}
        </div>
      </div>
      
      <div style={{ marginTop: 16, fontSize: 9, color: "#4a4f57", textAlign: "center", letterSpacing: 0.5 }}>
        RPM STRENGTH · TRACKMAN DATA
      </div>
    </div>
  );
}


